class NodeSetOperations:
    def time_difference_overlap(self, size):
        self.left.difference(self.right)

    def setup(self, size):
        self.left = NodeSet("node[1-%d]" % size,
                            resolver=RESOLVER_NOGROUP)
        self.right = NodeSet("node[%d-%d]" %
                             (size // 2, size + size // 2),
                             resolver=RESOLVER_NOGROUP)

